<script setup lang="ts">
import {localize} from './localization';

import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {DraftHistory} from '../../../packages/ui/draft-history';
import AssistantConnection from './AssistantConnection.vue';
import AssistantModels from './AssistantModels.vue';
import {defaultAssistantConfig,type AssistantConfig,type AssistantSettingsRequest} from '../../../packages/schema/assistant-config';
const newId=()=>crypto.randomUUID();
const props=defineProps<{language:'zh'|'en'}>(),zh=computed(()=>props.language==='zh'),config=ref<AssistantConfig>(defaultAssistantConfig()),tab=ref('models'),busy=ref(false),message=ref(''),failed=ref(false);
// Settings drafts have their own in-memory history. Credentials never enter
// the CAD repository, and a successful settings response starts a new boundary.
const settingsHistory=new DraftHistory<AssistantConfig>(),historyVersion=ref(0);
let previousConfig=JSON.stringify(config.value);
const canUndoSettings=computed(()=>{historyVersion.value;return settingsHistory.canUndo;}),canRedoSettings=computed(()=>{historyVersion.value;return settingsHistory.canRedo;});
watch(()=>JSON.stringify(config.value),value=>{if(value!==previousConfig){settingsHistory.record(JSON.parse(previousConfig),JSON.parse(value));previousConfig=value;historyVersion.value++;}},{flush:'post'});
function replaceConfig(value:AssistantConfig){config.value=value;previousConfig=JSON.stringify(value);settingsHistory.clear();historyVersion.value++;}
function moveSettings(redo=false){if(busy.value)return;const value=settingsHistory.move(JSON.parse(JSON.stringify(config.value)),redo);if(value){config.value=value;previousConfig=JSON.stringify(value);historyVersion.value++;}}
function settingsKey(event:KeyboardEvent){if(event.target instanceof Element&&event.target.closest('.modal-backdrop'))return;if(!(event.ctrlKey||event.metaKey))return;const key=event.key.toLowerCase();if(key!=='z'&&key!=='y')return;if(event.target instanceof Element&&event.target.closest('textarea,[contenteditable=true],input:not([type=number]):not([type=range]):not([type=checkbox]):not([type=radio]):not([type=color])'))return;event.preventDefault();event.stopPropagation();moveSettings(key==='y'||event.shiftKey);}
async function run(request:AssistantSettingsRequest){if(busy.value)return false;busy.value=true;message.value='';failed.value=false;try{const r=await window.fpcad.assistantSettings(request);if(!r.ok)throw Error(r.error);replaceConfig(r.config);message.value=request.action==='read'?'':r.tools?(zh.value?'已连接，工具：':localize('Connected, tools: '))+r.tools.join(', '):r.models?(zh.value?'已获取模型：':localize('Models loaded: '))+r.models.length:(zh.value?'设置已保存':localize('Settings saved'));return true;}catch(e){failed.value=true;message.value=errorText(String(e instanceof Error?e.message:e));return false;}finally{busy.value=false;}}
function errorText(message:string){
 const keys:Record<string,[string,string]>={MCP_RESPONSE_INVALID:['MCP 服务响应格式无效，请核对服务地址。','Invalid MCP response. Check the server address.'],MCP_TOOLS_INVALID:['MCP 服务返回的工具清单格式无效。','Invalid MCP tool list.'],PROVIDER_MANUAL_MODELS:['请在模型管理中填写控制台提供的模型或推理接入点标识。','Enter the model or endpoint ID from the provider console in Models.'],HTTP_REQUIRES_OPT_IN:['此服务使用 HTTP，请勾选该卡片的“允许 HTTP 连接”，或改用 HTTPS 地址。','Enable HTTP for this provider or use an HTTPS address.'],INVALID_ENDPOINT:['请输入完整的 HTTP 或 HTTPS 服务地址，不含账号、密码或查询参数。','Enter an HTTP or HTTPS base URL without credentials or query parameters.'],MODEL_LIST_INVALID:['服务返回的模型清单格式不匹配，请核对提供商类型和接口地址。','Model list does not match this provider protocol. Check provider type and base URL.'],PROVIDER_CHANGED:['提供商配置已改变，请重新获取模型。','Provider changed. Fetch models again.'],PROVIDER_UNAVAILABLE:['提供商不存在或未启用。','Provider is missing or disabled.'],MODEL_PAGINATION_INVALID:['模型列表分页无效，请检查服务响应。','Invalid model list pagination.']};
 for(const [key,text] of Object.entries(keys))if(message.includes(key))return localize(text[zh.value?0:1]);
 if(message.startsWith('PROVIDER_HTTP_'))return (zh.value?'连接失败，服务状态码：':localize('Connection failed, HTTP status: '))+message.slice(14);
 if(message.includes('fetch failed'))return zh.value?'无法连接服务，请检查地址、端口与服务是否启动。':localize('Cannot connect. Check address, port and server availability.');
 if(message.startsWith('['))return zh.value?'设置不完整，请检查提供商名称、地址和所选模型。':localize('Check provider name, address and model selection.');
 return message;
}
const save=()=>run({action:'save',config:JSON.parse(JSON.stringify(config.value))});
async function models(id:string){if(await save())await run({action:'models',providerId:id});}
async function testMcp(id:string){if(await save())await run({action:'mcp-test',serverId:id});}
async function importSkill(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(file.size>100000){failed.value=true;message.value=zh.value?'技能文件过大':localize('Skill file too large');return;}config.value.skills.push({id:newId(),name:file.name,content:await file.text(),enabled:true});input.value='';}
onMounted(()=>{window.addEventListener('keydown',settingsKey);void run({action:'read'});});onUnmounted(()=>window.removeEventListener('keydown',settingsKey));
</script>
<template><main class="assistant-page" aria-label="AI 助手管理"><div class="assistant-title"><div><h1>{{zh?'AI 助手':localize('AI assistant')}}</h1><p>{{zh?'管理模型连接、技能与 MCP 服务。配置保存在本机，API 密钥加密保存。':localize('Manage model connections, skills and MCP services. Settings stay local; API keys are encrypted.')}}</p></div><div class="settings-history"><button :disabled="busy||!canUndoSettings" @click="moveSettings()">{{zh?'撤销设置':localize('Undo settings')}}</button><button :disabled="busy||!canRedoSettings" @click="moveSettings(true)">{{zh?'重做设置':localize('Redo settings')}}</button><button class="primary" :disabled="busy" @click="save">{{zh?'保存设置':localize('Save settings')}}</button></div></div><nav role="tablist"><button v-for="item in [['models','模型管理','Models'],['skills','技能','Skills'],['mcp','MCP','MCP'],['connection','软件连接','CAD connection']]" :key="item[0]" role="tab" :aria-selected="tab===item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]">{{zh?item[1]:localize(item[2])}}</button></nav><p v-if="message" :role="failed?'alert':'status'" :class="{error:failed}">{{message}}</p><section role="tabpanel"><fieldset :disabled="busy">
<AssistantModels v-if="tab==='models'" :config="config" :language="language" @models="models"/>
<template v-else-if="tab==='skills'"><p>{{zh?'导入或编写技能说明，按需启用。保存配置不会执行技能中的命令。':localize('Import or write skill instructions and enable them as needed. Saving a skill does not execute its commands.')}}</p><label>{{zh?'导入 SKILL.md':localize('Import SKILL.md')}}<input type="file" accept=".md,.txt" @change="importSkill"></label><article v-for="s in config.skills" :key="s.id"><div class="row"><input v-model="s.enabled" type="checkbox" :aria-label="zh?'启用技能':localize('Enable skill')"><input v-model="s.name" :aria-label="zh?'技能名称':localize('Skill name')"><button @click="config.skills=config.skills.filter(v=>v.id!==s.id)">{{zh?'删除':localize('Delete')}}</button></div><textarea v-model="s.content" rows="10" :aria-label="zh?'技能内容':localize('Skill instructions')"/></article><button @click="config.skills.push({id:newId(),name:zh?'新技能':localize('New skill'),content:'',enabled:true})">＋ {{zh?'新建技能':localize('New skill')}}</button></template>
<template v-else-if="tab==='mcp'"><p>{{zh?'支持 Streamable HTTP MCP 服务。连接测试读取工具清单，不会执行工具。':localize('Streamable HTTP MCP servers. Connection tests list tools without executing them.')}}</p><article v-for="s in config.mcp" :key="s.id"><div class="row"><input v-model="s.enabled" type="checkbox" :aria-label="zh?'启用 MCP':localize('Enable MCP')"><input v-model="s.name" :aria-label="zh?'MCP 名称':localize('MCP name')"><button @click="config.mcp=config.mcp.filter(v=>v.id!==s.id)">{{zh?'删除':localize('Delete')}}</button></div><label>URL<input v-model="s.url" type="url"></label><button @click="testMcp(s.id)">{{zh?'测试连接并查看工具':localize('Test connection and list tools')}}</button></article><button @click="config.mcp.push({id:newId(),name:zh?'本地 MCP':localize('Local MCP'),url:'http://127.0.0.1:8000/mcp',enabled:true})">＋ {{zh?'添加 MCP':localize('Add MCP')}}</button></template>
<AssistantConnection v-else :language="language"/>
</fieldset></section></main></template>
<style scoped>.settings-history{display:flex;gap:8px;flex-wrap:wrap}.assistant-page{flex:1;min-height:0;overflow:auto;padding:24px 5%;background:var(--panel-soft)}.assistant-title{display:flex;align-items:center;justify-content:space-between;gap:20px}.assistant-title h1{margin:0}.assistant-page nav{display:flex;gap:8px;border-bottom:1px solid var(--border);padding:16px 0}.active{background:var(--selected);border-color:var(--accent)}article{background:var(--panel);border:1px solid var(--border);padding:18px;margin:14px 0;border-radius:6px}fieldset{border:0;padding:0;min-width:0}.row{display:flex;align-items:center;gap:12px;margin-bottom:12px}.row input:not([type=checkbox]){flex:1}.row label{display:flex;align-items:center;gap:8px;white-space:nowrap}input[type=checkbox]{width:auto}textarea{width:100%;min-height:100px}p,small{color:var(--text-muted);line-height:1.6}small{display:block;margin-top:8px}.error{color:var(--danger)}section{max-width:1200px}.provider-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(350px,100%),1fr));gap:16px;margin:16px 0}.provider-card{display:flex;flex-direction:column;gap:12px;margin:0;min-width:0}.provider-card label{display:flex;flex-direction:column;gap:6px}.provider-card input,.provider-card select{margin:0}.provider-card .row{margin:0}.provider-card .row label,.provider-card .http-option{flex-direction:row;align-items:center}.provider-card .row strong{flex:1}.provider-card small{margin:0}.provider-card>button{align-self:flex-start}.assistant-page fieldset>label+label{margin-top:12px}.assistant-page article>textarea{margin-top:12px}</style>
